1	// The digest's pure half: which three repos this morning's mail is about, and what
2	// it says. No I/O, no clock of its own — worker.mjs reads the snapshot and passes the
3	// day in, so every branch here is reachable from a test with a fixed date.
4	
5	import { WORK_PREFIX } from '../../../../../shared/packs/claudinite-tasks/queue/work-item.mjs';
6	import { isDispatchTitle } from '../../../../../shared/packs/claudinite-tasks/dispatch.mjs';
7	
8	export const REPOS_PER_DIGEST = 3;
9	export const ISSUES_PER_REPO = 5;
10	
11	// The machinery is the busiest actor in this fleet, and a queue item outnumbers the
12	// project work it dispatches — five titles per repo would be five work items on every
13	// active member. Recognized by the engine's own constant and its own predicate, since
14	// both title formats are the scheduler's to change: `[claudinite-work]` today, and
15	// `[claudinite-task]` in the history the snapshot still carries.
16	//
17	// COUNTED, NOT DROPPED: how much of the fleet's day went on servicing itself is a true
18	// thing about the repo, so it is tallied on its own line rather than made invisible.
19	export const isMaintenance = (issue) =>
20	  String(issue?.title ?? '').trim().startsWith(WORK_PREFIX) || isDispatchTitle(issue?.title);
21	
22	// Whole days since the Unix epoch, in UTC. The rotation's only input, so the digest
23	// is a function of the date rather than of when in the night the run happened: a run
24	// at 03:59 and a re-run at 04:01 pick the same three repos.
25	export const dayNumber = (now) => Math.floor(Date.UTC(
26	  now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(),
27	) / 86_400_000);
28	
29	// Day N takes the roster's entries 3N, 3N+1 and 3N+2, wrapping. The roster is sorted,
30	// so the sequence depends on the fleet's membership rather than on the order the
31	// snapshot happened to enumerate it in — and a repo joining or leaving shifts the
32	// rotation without ever stalling it on one member.
33	//
34	// Every repo comes round before any repeats while the fleet is larger than three:
35	// consecutive days start three apart, so the whole roster is covered in
36	// ceil(n / 3) days whatever n is. A fleet of three or fewer sends all of it.
37	export function chooseRepos(roster, day) {
38	  const names = [...roster].sort();
39	  if (names.length <= REPOS_PER_DIGEST) return names;
40	  const start = ((day * REPOS_PER_DIGEST) % names.length + names.length) % names.length;
41	  return Array.from({ length: REPOS_PER_DIGEST }, (_, i) => names[(start + i) % names.length]);
42	}
43	
44	// The snapshot's repos as { repo, openIssues, issues }, keyed for lookup. A repo in
45	// the roster with no entry is not possible today — the roster IS the snapshot's repo
46	// list — but the digest states an absent count as unknown rather than as zero, so a
47	// future roster from elsewhere degrades honestly.
48	export function digestFor(snapshot, day) {
49	  const byName = new Map((snapshot.repos ?? []).map((r) => [r.repo, r]));
50	  const chosen = chooseRepos([...byName.keys()], day);
51	  return chosen.map((name) => {
52	    const entry = byName.get(name);
53	    const issues = entry?.issues ?? [];
54	    const theirs = issues.filter((i) => !isMaintenance(i));
55	    return {
56	      repo: name,
57	      url: `https://github.com/${name}`,
58	      // `openIssues` is the repo's own count; `issues` is what the snapshot carried,
59	      // which the snapshot's own paging can leave shorter. Neither stands in for a
60	      // missing other.
61	      openIssues: entry?.openIssues ?? (entry ? issues.length : null),
62	      maintenance: issues.length - theirs.length,
63	      // Newest first: the snapshot lists them in the API's default order, which is
64	      // already newest-updated, and the digest is a nudge rather than a backlog.
65	      top: theirs.slice(0, ISSUES_PER_REPO),
66	    };
67	  });
68	}
69	
70	// A repo whose only open issues are the queue's is a different thing from a repo with
71	// an empty tracker, and the digest says which.
72	const nothingToShow = (r) => (r.maintenance
73	  ? 'Nothing open but the queue\'s own items.'
74	  : 'No open issues.');
75	
76	const escapeHtml = (s) => String(s)
77	  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
78	  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
79	
80	const countLine = (r) => {
81	  const open = r.openIssues === null
82	    ? 'open issues unknown'
83	    : `${r.openIssues} open issue${r.openIssues === 1 ? '' : 's'}`;
84	  return r.maintenance ? `${open}, ${r.maintenance} of them the queue's own` : open;
85	};
86	
87	export const subjectFor = (entries, now) =>
88	  `Fleet digest ${now.toISOString().slice(0, 10)}: ${entries.map((e) => e.repo.split('/').pop()).join(', ')}`;
89	
90	// Inline styles and no images: a mail client applies no stylesheet and blocks remote
91	// content by default, so anything in a <style> block or an <img> is decoration the
92	// recipient may never see.
93	export function htmlBody(entries, { generated }) {
94	  const blocks = entries.map((r) => {
95	    const issues = r.top.length
96	      ? `<ul style="margin:8px 0 0;padding-left:20px">${r.top.map((i) =>
97	        `<li style="margin:2px 0"><a href="${escapeHtml(r.url)}/issues/${i.number}">#${i.number}</a> ${escapeHtml(i.title)}</li>`).join('')}</ul>`
98	      : `<p style="margin:8px 0 0;color:#666">${escapeHtml(nothingToShow(r))}</p>`;
99	    return `<div style="margin:0 0 24px">`
100	      + `<h2 style="margin:0;font-size:16px"><a href="${escapeHtml(r.url)}">${escapeHtml(r.repo)}</a></h2>`
101	      + `<p style="margin:2px 0 0;color:#666;font-size:13px">${countLine(r)}</p>`
102	      + `${issues}</div>`;
103	  }).join('');
104	  return `<div style="font-family:-apple-system,Segoe UI,Helvetica,Arial,sans-serif;font-size:14px;line-height:1.5">`
105	    + `<p style="margin:0 0 24px;color:#666">Three repos from the fleet, in rotation.</p>`
106	    + `${blocks}`
107	    + `<p style="margin:32px 0 0;color:#999;font-size:12px">From the fleet issues snapshot taken ${escapeHtml(generated)}.</p></div>`;
108	}
109	
110	export function textBody(entries, { generated }) {
111	  const blocks = entries.map((r) => {
112	    const issues = r.top.length
113	      ? r.top.map((i) => `  #${i.number} ${i.title}`).join('\n')
114	      : `  ${nothingToShow(r)}`;
115	    return `${r.repo} — ${countLine(r)}\n${r.url}\n${issues}`;
116	  }).join('\n\n');
117	  return `Three repos from the fleet, in rotation.\n\n${blocks}\n\nFrom the fleet issues snapshot taken ${generated}.\n`;
118	}

